const original = { label: "Original Woodshed musicianship material", scope: "Newly composed teaching music and tasks; the form pieces are complete short works, not excerpts from another composition." };
const grand = (title, right, left, { key = "C", meter = "4/4", unit = "1/4", tempo } = {}) => {
  if (right.length !== left.length) throw new Error(`Unmatched hands: ${title}`);
  const lines = [];
  for (let i = 0; i < right.length; i += 4) {
    const end = i + 4 >= right.length ? " |]" : " |";
    lines.push(`[V:1] ${right.slice(i, i + 4).join(" | ")}${end}`);
    lines.push(`[V:2] ${left.slice(i, i + 4).join(" | ")}${end}`);
  }
  return `X:1\nT:${title}\nM:${meter}\nL:${unit}\n${tempo ? `Q:"${tempo}"\n` : ""}K:${key}\n%%staves {1 2}\nV:1 clef=treble\nV:2 clef=bass\n${lines.join("\n")}`;
};
const rests = (n, value = "z4") => Array(n).fill(value);
